import * as React from "react";
import { cx } from "./cx";

export interface ProgressProps extends React.HTMLAttributes<HTMLDivElement> {
  value: number;
  max?: number;
  /** Label above the bar; the percentage lives here, never inside the bar. */
  label?: React.ReactNode;
}

export function Progress({ value, max = 100, label, className, ...props }: ProgressProps) {
  const pct = Math.min(100, Math.max(0, max === 0 ? 0 : (value / max) * 100));
  return (
    <div className={cx(className)} {...props}>
      {label != null && (
        <div className="rs-progress-head">
          <span>{label}</span>
          <span>{Math.round(pct)}%</span>
        </div>
      )}
      <div
        className="rs-progress"
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={max}
        aria-valuenow={value}
      >
        <span style={{ width: `${pct}%` }} />
      </div>
    </div>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Progress: the percentage lives in the label, never in the bar ── */
.rs-progress-head{display:flex;justify-content:space-between;font-size:12px;font-weight:500;color:var(--text-secondary);letter-spacing:-.01em;margin-bottom:7px}
.rs-progress{height:4px;background:var(--divider-subtle);border-radius:2px;overflow:hidden}
.rs-progress span{display:block;height:100%;background:var(--text);border-radius:2px}
